package tokens

// Cross-implementation check: tests/vectors.json is generated by the Python reference
// (python -m tests.gen_vectors); every case must verify identically here.

import (
	"bytes"
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/elliptic"
	"encoding/hex"
	"encoding/json"
	"math/big"
	"os"
	"strings"
	"testing"

	"github.com/cloudflare/circl/sign/mldsa/mldsa44"
)

type vcase struct {
	Token  string `json:"token"`
	URL    string `json:"url"`
	Valid  bool   `json:"valid"`
	Reason string `json:"reason"`
}

type vectors struct {
	Doc struct {
		Now    float64          `json:"now"`
		VMax   int64            `json:"v_max"`
		Tau    int64            `json:"tau_skew"`
		AlgIDs map[string]uint8 `json:"alg_ids"`
	} `json:"doc"`
	Th []struct {
		Kid, Epoch        uint32
		Type, Level       uint8
		Index, Tenant     uint32
		Data, Tweak, Out  string
		N                 int
	} `json:"th"`
	Ember []struct {
		RootSigner string  `json:"root_signer"`
		N          int     `json:"n"`
		NLeaves    int     `json:"N"`
		PK         string  `json:"pk_hex"`
		SR         string  `json:"signed_root_hex"`
		Root       string  `json:"root_hex"`
		RootMsg    string  `json:"root_msg_hex"`
		Cases      []vcase `json:"cases"`
	} `json:"ember"`
	PerToken []map[string]interface{} `json:"pertoken"`
}

func mustHex(t *testing.T, s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestSharedVectors(t *testing.T) {
	path := os.Getenv("EMBER_VECTORS")
	if path == "" {
		path = "../../tests/vectors.json"
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Skip("no shared vectors at", path)
	}
	var v vectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	now := int64(v.Doc.Now)
	checked := 0
	for _, x := range v.Th {
		tw := Tweak(x.Kid, x.Epoch, x.Type, x.Level, x.Index, x.Tenant)
		if hex.EncodeToString(tw) != x.Tweak || hex.EncodeToString(Th(tw, mustHex(t, x.Data), x.N)) != x.Out {
			t.Fatalf("Th vector mismatch")
		}
		checked++
	}
	for _, e := range v.Ember {
		alg := v.Doc.AlgIDs[e.RootSigner] << 4
		if e.N == 32 {
			alg |= AlgN32
		}
		sr, err := UnmarshalRoot(mustHex(t, e.SR), alg)
		if err != nil {
			t.Fatal(err)
		}
		if hex.EncodeToString(sr.Msg()) != e.RootMsg || hex.EncodeToString(sr.R) != e.Root {
			t.Fatalf("%s n=%d N=%d: root msg mismatch", e.RootSigner, e.N, e.NLeaves)
		}
		pk := mustHex(t, e.PK)
		var m44 *mldsa44.PublicKey
		var ed ed25519.PublicKey
		switch e.RootSigner {
		case "ML-DSA-44":
			m44 = new(mldsa44.PublicKey)
			if err := m44.UnmarshalBinary(pk); err != nil {
				t.Fatal(err)
			}
		case "Ed25519":
			ed = pk
		default:
			ed = pk[:32]
			m44 = new(mldsa44.PublicKey)
			if err := m44.UnmarshalBinary(pk[32:]); err != nil {
				t.Fatal(err)
			}
		}
		if !VerifyRootWith(m44, ed, sr) {
			t.Fatalf("%s n=%d N=%d: root signature rejected", e.RootSigner, e.N, e.NLeaves)
		}
		for _, c := range e.Cases {
			ok := false
			cl, enc, b, err := ParseEmber(c.Token)
			if err == nil && b.Alg == alg && now <= cl.Expires+v.Doc.Tau &&
				cl.Expires*1000 <= int64(sr.TStartMs)+int64(sr.DeltaMs)+(v.Doc.VMax+v.Doc.Tau)*1000 &&
				strings.HasPrefix(c.URL, cl.URLPrefix) {
				ok = VerifyEmberPath(cl, enc, b, sr)
			}
			if ok != c.Valid {
				t.Fatalf("%s n=%d N=%d case %q: go=%v python=%v", e.RootSigner, e.N, e.NLeaves, c.Reason, ok, c.Valid)
			}
			checked++
		}
	}
	for _, p := range v.PerToken {
		sid := p["scheme"].(string)
		k := &Keys{}
		ver := NewVerifier(k)
		hx := func(key string) []byte { return mustHex(t, p[key].(string)) }
		switch sid {
		case "B1":
			k.HMAC = hx("hmac_key_hex")
		case "B2":
			k.EdPub = hx("ed25519_pk_hex")
		case "B3":
			b := hx("p256_pk_uncompressed_hex")
			k.EC = &ecdsa.PrivateKey{PublicKey: ecdsa.PublicKey{Curve: elliptic.P256(), X: new(big.Int).SetBytes(b[1:33]), Y: new(big.Int).SetBytes(b[33:])}}
		case "B5":
			k.M44Pub = new(mldsa44.PublicKey)
			k.M44Pub.UnmarshalBinary(hx("mldsa44_pk_hex"))
		case "B11":
			master := new(mldsa44.PublicKey)
			master.UnmarshalBinary(hx("mldsa44_master_pk_hex"))
			id, pk, _, err := VerifyDelegCert(master, hx("cert_hex"))
			if err != nil {
				t.Fatalf("B11 cert: %v", err)
			}
			ver.DelegPub[id] = pk
		case "B12":
			ver.EpochK[uint32(p["epoch"].(float64))] = hx("k_e_hex")
		}
		for _, ci := range p["cases"].([]interface{}) {
			c := ci.(map[string]interface{})
			cl, err := ver.VerifyPerToken(strings.ToLower(sid), c["token"].(string))
			ok := err == nil && strings.HasPrefix(c["url"].(string), cl.URLPrefix) && now <= cl.Expires+v.Doc.Tau
			if ok != c["valid"].(bool) {
				t.Fatalf("%s: go=%v python=%v (%v)", sid, ok, c["valid"], err)
			}
			checked++
		}
	}
	_ = bytes.Equal
	t.Logf("shared vectors: %d checks passed (%s)", checked, path)
}
